insert into public.cards (id, deck_id, kind, topic, badge, question, passage, answer, wrong, criteria, explanation, source_label, source_page, source_slide, source_url, sort, figure_src, figure_alt) values
  ('korean-newyork-001', 'korean-newyork', 'choice', '갈래와 구성', '「뉴욕제과점」', '이 작품의 갈래는?', null, '자전적 소설', array['역사 소설', '우화 소설', '풍자 소설'], '{}'::text[], '「뉴욕제과점」은 작가가 뉴욕제과점에서 보낸 유년의 체험을 바탕으로 쓴 자전적 소설이다.', '김연수 「뉴욕제과점」 · 교과서 본문과 학습 노트', null, null, null, 0, null, null),
  ('korean-newyork-002', 'korean-newyork', 'choice', '갈래와 구성', '「뉴욕제과점」', '이 작품의 시점은?', null, '1인칭 주인공 시점', array['1인칭 관찰자 시점', '3인칭 관찰자 시점', '전지적 작가 시점'], '{}'::text[], '작품 속 ''나''가 주인공이 되어 자신의 이야기를 직접 들려주므로 1인칭 주인공 시점이다.', '김연수 「뉴욕제과점」 · 교과서 본문과 학습 노트', null, null, null, 1, null, null),
  ('korean-newyork-003', 'korean-newyork', 'choice', '갈래와 구성', '「뉴욕제과점」', '작품 전체의 구성 방식은?', null, '역행적 구성', array['순차적 구성', '환몽 구성', '액자식 구성'], '{}'::text[], '현재에서 과거의 추억으로 거슬러 올라가므로 전체는 역행적 구성이다. 그 안의 삽화들은 순차적으로 이어진다.', '김연수 「뉴욕제과점」 · 교과서 본문과 학습 노트', null, null, null, 2, null, null),
  ('korean-newyork-004', 'korean-newyork', 'choice', '갈래와 구성', '뉴욕제과점이라는 배경', '이 작품에서 배경이 하는 역할은?', null, '주제 의식을 드러냄', array['단순한 무대 장치', '인물 간 갈등을 해소함', '시대를 풍자함'], '{}'::text[], '뉴욕제과점이라는 배경은 추억이 삶을 살아가게 하는 힘이라는 주제 의식으로 이어진다.', '김연수 「뉴욕제과점」 · 교과서 본문과 학습 노트', null, null, null, 3, null, null),
  ('korean-newyork-005', 'korean-newyork', 'choice', '갈래와 구성', '「뉴욕제과점」', '이 작품의 주제로 가장 알맞은 것은?', null, '추억이 삶을 살게 하는 힘', array['변해 가는 고향 비판', '가난을 이겨 낸 성공담', '세대 간의 갈등'], '{}'::text[], '''나''는 사라진 뉴욕제과점이 남긴 추억의 힘으로 세상을 살아갈 수 있음을 깨닫는다.', '김연수 「뉴욕제과점」 · 교과서 본문과 학습 노트', null, null, null, 4, null, null),
  ('korean-newyork-006', 'korean-newyork', 'choice', '구절의 의미', '"나는 이 소설만은 연필로 쓰기로 결심했다."', '이 결심에 담긴 마음으로 알맞은 것은?', null, '정성 들여 고쳐 가며 쓰려 함', array['빨리 끝내고 싶어 함', '남에게 숨기고 싶어 함', '어머니의 뜻을 따르려 함'], '{}'::text[], '연필은 지우고 고치기 쉽다. 이 소설만은 정성을 들여 수정을 거치며 쓰겠다는 마음이 담겨 있다.', '김연수 「뉴욕제과점」 · 교과서 본문과 학습 노트', null, null, null, 5, null, null),
  ('korean-newyork-007', 'korean-newyork', 'choice', '구절의 의미', '"물론 인생은 그런 게 아니다."', '이 말에 담긴 뜻은?', null, '인생은 예상대로 흐르지 않음', array['인생은 늘 행복하기만 함', '노력하면 무엇이든 이룸', '고향은 언제나 변하지 않음'], '{}'::text[], '뉴욕제과점이 사라졌다는 사실과 함께, 인생은 항상 예상대로 흘러가지 않는다는 뜻을 담고 있다.', '김연수 「뉴욕제과점」 · 교과서 본문과 학습 노트', null, null, null, 6, null, null),
  ('korean-newyork-008', 'korean-newyork', 'choice', '구절의 의미', '"이젠 더 이상 제과점을 하지 않아요."', '''나''가 고향 사람들에게 이 말을 하는 까닭은?', null, '그 일이 큰일임을 알리려고', array['어머니를 원망하려고', '새 가게를 자랑하려고', '고향을 잊으려고'], '{}'::text[], '''나''에게 제과점이 문을 닫은 것은 큰일이다. 이 일이 큰일임을 상대에게 알려 주기 위해 하는 말이다.', '김연수 「뉴욕제과점」 · 교과서 본문과 학습 노트', null, null, null, 7, null, null),
  ('korean-newyork-009', 'korean-newyork', 'choice', '구절의 의미', '"고향 사람들과 얘기할 때, 나는 곧잘 문맥을 놓친다."', '이 장면이 드러내는 것은?', null, '제과점을 보는 시각 차이', array['''나''의 기억력 감퇴', '고향 사람들의 무관심한 말투', '고향 사투리의 차이'], '{}'::text[], '''나''는 뉴욕제과점에 큰 의미를 부여하지만 고향 사람들은 그것에 관심이 없다. 서로 다르게 바라보니 대화가 엇갈린다.', '김연수 「뉴욕제과점」 · 교과서 본문과 학습 노트', null, null, null, 8, null, null),
  ('korean-newyork-010', 'korean-newyork', 'choice', '구절의 의미', '"나란 존재는 그 거리 … 이루어진 어떤 것이다."', '이 구절에서 뉴욕제과점의 의미는?', null, '''나''의 정체성을 기른 곳', array['어머니의 일터일 뿐인 곳', '어릴 때 떠나고 싶던 곳', '고향 사람들의 쉼터'], '{}'::text[], '''나''는 뉴욕제과점에서의 유년의 기억으로 이루어져 있으며, 뉴욕제과점은 ''나''의 정체성을 기르는 데 큰 영향을 주었다.', '김연수 「뉴욕제과점」 · 교과서 본문과 학습 노트', null, null, null, 9, null, null),
  ('korean-newyork-011', 'korean-newyork', 'choice', '구절의 의미', '의식과 정체성을 이루던 곳이 사라진 ''나''', '''나''가 이런 자신을 빗댄 말은?', null, '실향민', array['이방인', '나그네', '망명객'], '{}'::text[], '''나''의 의식과 정체성을 이루던 뉴욕제과점이 사라졌으므로, 고향을 잃은 실향민처럼 느낀다.', '김연수 「뉴욕제과점」 · 교과서 본문과 학습 노트', null, null, null, 10, null, null),
  ('korean-newyork-012', 'korean-newyork', 'choice', '구절의 의미', '"… 어렵던 그 시절 그 거리를 오랫동안 공들여 천천히 다시 걷고 싶다."', '이 구절에 담긴 ''나''의 마음은?', null, '그 시절 그 거리로 돌아가고 싶음', array['다가올 죽음이 몹시 두려움', '고향을 영영 떠나고 싶음', '어렵던 그 시절을 잊어버리고 싶음'], '{}'::text[], '죽음을 앞두고 삶을 되돌아볼 기회가 온다면, 다른 시절을 줄여서라도 뉴욕제과점이 있던 그 시절 그 거리를 다시 걷고 싶다는 마음이다.', '김연수 「뉴욕제과점」 · 교과서 본문과 학습 노트', null, null, null, 11, null, null),
  ('korean-newyork-013', 'korean-newyork', 'choice', '구절의 의미', '"그들로서는 당연한 마음이겠지만, 나는 그런 사람들이 좀 야속하다."', '이 말에서 드러나는 ''나''의 마음은?', null, '제과점을 향한 애틋함', array['고향 사람들을 향한 분노', '고향을 떠난 후회', '어머니에 대한 미안함'], '{}'::text[], '제과점이 있던 곳에 다시 가 보고 싶어 하지 않는 고향 사람들이 야속하게 느껴질 만큼 ''나''는 뉴욕제과점을 애틋하게 여긴다.', '김연수 「뉴욕제과점」 · 교과서 본문과 학습 노트', null, null, null, 12, null, null),
  ('korean-newyork-014', 'korean-newyork', 'choice', '구절의 의미', '"정상적인 세상에서 정상적 … 정상적인 일이다."', '''정상적''을 되풀이한 효과는?', null, '반어적으로 상실감 강조', array['사라짐을 기쁘게 받아들임', '세상의 질서를 찬양함', '고향 사람들을 비판함'], '{}'::text[], '''정상적''을 네 번 되풀이하며 먼저 생긴 것이 먼저 없어지는 것은 당연하다고 말하지만, 이는 반어적 표현으로 뉴욕제과점이 사라진 상실감을 강조한다.', '김연수 「뉴욕제과점」 · 교과서 본문과 학습 노트', null, null, null, 13, null, null),
  ('korean-newyork-015', 'korean-newyork', 'choice', '구절의 의미', '"정상적인 일이다. 그러니까 … 그와 마찬가지다."', '이 구절에 쓰인 주된 표현법은?', null, '반어법', array['직유법', '설의법', '의인법'], '{}'::text[], '먼저 생긴 것이 먼저 없어지는 것이 정상이라고 말하지만 속뜻은 상실의 아픔이다. 겉말과 속뜻이 반대인 반어법이다.', '김연수 「뉴욕제과점」 · 교과서 본문과 학습 노트', null, null, null, 14, null, null),
  ('korean-newyork-016', 'korean-newyork', 'choice', '구절의 의미', '"그거보다는 내가 더 많이 팔았지."', '이 말에 드러난 어머니의 마음은?', null, '제과점에 대한 자부심', array['장사에 대한 후회', '아들에 대한 원망', '손님에 대한 불만'], '{}'::text[], '어머니는 뉴욕제과점을 꾸려 온 일에 자부심을 가지고 있다.', '김연수 「뉴욕제과점」 · 교과서 본문과 학습 노트', null, null, null, 15, null, null),
  ('korean-newyork-017', 'korean-newyork', 'choice', '구절의 의미', '"제일 훌륭한 것은 대학교 등록금이 아니라 그 웃음이라고 말하면 …"', '''나''가 더 고맙게 여긴 것은?', null, '어머니의 긍정적인 성격', array['등록금을 마련해 준 일', '빵을 팔아 번 돈', '제과점의 오랜 역사'], '{}'::text[], '''나''는 등록금을 마련해 준 것보다 어머니가 긍정적이고 낙천적인 성격이 된 것을 더 좋아하고 고맙게 여긴다.', '김연수 「뉴욕제과점」 · 교과서 본문과 학습 노트', null, null, null, 16, null, null),
  ('korean-newyork-018', 'korean-newyork', 'choice', '구절의 의미', '불빛, 사탕', '이 소재들이 ''나''에게 뜻하는 것은?', null, '힘들 때 떠올리는 추억', array['애써 잊고 싶은 과거', '어머니가 겪은 고생', '고향이 겪은 가난'], '{}'::text[], '불빛과 사탕은 뉴욕제과점의 추억이다. ''나''는 힘들고 헤어질 때마다 이 추억을 떠올린다.', '김연수 「뉴욕제과점」 · 교과서 본문과 학습 노트', null, null, null, 17, null, null),
  ('korean-newyork-019', 'korean-newyork', 'choice', '결말과 깨달음', '내가 사라진 뒤에도 아이가 살아갈 것을 "''상식적으로'' 받아들일 수 있게 됐다."', '이 말에 드러난 ''나''의 태도는?', null, '담담히 받아들임', array['분노하며 거부함', '모른 척 외면함', '두려워 피함'], '{}'::text[], '아이가 생긴 뒤 ''나''는 자신이 사라진 뒤에도 아이가 세상을 살아갈 것이라는 사실을 담담하게 받아들이게 되었다.', '김연수 「뉴욕제과점」 · 교과서 본문과 학습 노트', null, null, null, 18, null, null),
  ('korean-newyork-020', 'korean-newyork', 'choice', '구절의 의미', '국밥집 안에서 "나는 더 이상 고개를 들고 실내를 바라볼 수 없었다."', '이 장면에서 ''나''의 마음은?', null, '울컥함', array['홀가분함', '무관심함', '통쾌함'], '{}'::text[], '옛 가게의 모습과 가족의 모습이 겹쳐 보이자 감정이 북받쳐 고개를 들 수 없을 만큼 울컥한 것이다.', '김연수 「뉴욕제과점」 · 교과서 본문과 학습 노트', null, null, null, 19, null, null),
  ('korean-newyork-021', 'korean-newyork', 'choice', '구절의 의미', '"역전 거리의 불빛들이 둥글게 아롱져 보였다."', '이 표현이 나타내는 것은?', null, '눈물이 차오름', array['안개가 낌', '불빛이 밝아짐', '잠이 쏟아짐'], '{}'::text[], '눈물이 차올라 불빛이 둥글게 아롱져 보이는 것이다. 슬픔을 직접 말하지 않고 보이는 모습으로 드러낸다.', '김연수 「뉴욕제과점」 · 교과서 본문과 학습 노트', null, null, null, 20, null, null),
  ('korean-newyork-022', 'korean-newyork', 'choice', '구절의 의미', '"세상을 살아가는 데 그렇게 많은 불빛이 필요한 것은 아니다."', '이 구절의 의미는?', null, '작은 추억으로도 살아갈 수 있음', array['세상은 언제나 어두운 곳임', '많은 돈은 필요하지 않음', '지난 일은 잊어야 살 수 있음'], '{}'::text[], '불빛은 마음에 간직한 추억이다. 많지 않아도 조금의 추억만 있으면 그것을 원동력 삼아 세상을 살아갈 수 있다는 뜻이다.', '김연수 「뉴욕제과점」 · 교과서 본문과 학습 노트', null, null, null, 21, null, null),
  ('korean-newyork-023', 'korean-newyork', 'choice', '구절의 의미', '"나도 누군가에게 내가 없어진 … 알게 됐다."', '''나''가 알게 된 것은?', null, '없어져도 누군가의 힘이 됨', array['혼자서는 살 수 없음', '결국 모두 잊힘', '고향은 변하지 않음'], '{}'::text[], '이별하더라도 남아 있으며, 내가 없더라도 누군가에게 소중한 존재로서 살아갈 힘을 줄 수 있음을 알게 되었다.', '김연수 「뉴욕제과점」 · 교과서 본문과 학습 노트', null, null, null, 22, null, null),
  ('korean-newyork-024', 'korean-newyork', 'choice', '어머니', '「뉴욕제과점」 · 제과점을 꾸려 삼남매를 길러 낸 어머니', '이 행동에서 드러나는 성격은?', null, '억척스럽고 책임감 강함', array['소심하고 겁이 많음', '허영심이 강함', '무심하고 냉정함'], '{}'::text[], '어머니는 제과점을 경영해 삼남매를 길러 냈다. 억척스럽고 책임감이 강한 인물이다.', '김연수 「뉴욕제과점」 · 교과서 본문과 학습 노트', null, null, null, 23, null, null),
  ('korean-newyork-025', 'korean-newyork', 'choice', '어머니', '수술 후 사소한 일에도 웃는 어머니', '이 모습에서 알수있는 성격의 변화는?', null, '긍정적이고 낙천적임', array['억척스럽고 고집셈', '자존심이 강함', '소극적이고 비관적임'], '{}'::text[], '과거 강인한 모습의 어머니는 수술 후 사소한 일에도 웃는 모습에서 긍정적이고 낙천적인 성격으로 변한 것을 알 수 있다.', '김연수 「뉴욕제과점」 · 교과서 본문과 학습 노트', null, null, null, 24, null, null),
  ('korean-newyork-026', 'korean-newyork', 'choice', '어머니', '「뉴욕제과점」 · 등록금까지만 대고 졸업 후엔 돈을 주지 않음', '어머니가 중요하게 여긴 것은?', null, '자립심', array['체면', '학벌', '저축'], '{}'::text[], '어머니는 ''나''에게 대학 등록금까지만 지원하고 졸업 후에는 돈을 주지 않았다. 자립심을 중요하게 여긴 것이다.', '김연수 「뉴욕제과점」 · 교과서 본문과 학습 노트', null, null, null, 25, null, null),
  ('korean-newyork-027', 'korean-newyork', 'choice', '어머니', '「뉴욕제과점」 · 버리는 빵을 검정 봉투에 가리는 어머니', '이 행동에서 드러나는 성격은?', null, '자존심이 강함', array['낭비가 심함', '손님을 속이려 함', '위생에 철저함'], '{}'::text[], '팔지 못해 버리는 빵을 남이 보지 않게 검정 봉투에 가린다. 자존심이 강한 성격이다.', '김연수 「뉴욕제과점」 · 교과서 본문과 학습 노트', null, null, null, 26, null, null),
  ('korean-newyork-028', 'korean-newyork', 'choice', '어머니', '「뉴욕제과점」 · 장사가 안 돼도 가게를 오래 버틴 어머니', '이 행동에서 드러나는 성격은?', null, '소중한 것에 애착이 강함', array['고집이 세고 무책임함', '돈 욕심이 많음', '변화를 즐김'], '{}'::text[], '장사가 안 되어도 오래 버틴 것은 소중히 여기는 것에 대한 애착이 강하기 때문이다.', '김연수 「뉴욕제과점」 · 교과서 본문과 학습 노트', null, null, null, 27, null, null),
  ('korean-newyork-029', 'korean-newyork', 'choice', '어머니', '「뉴욕제과점」 · 버리는 빵을 가림 A / 등록금까지만 지원 B', 'A, B에서 드러나는 성격은? A–B는?', null, '자존심–자립심 중시', array['자립심 중시–자존심', '책임감–낙천성', '애착–자존심'], '{}'::text[], '버리는 빵을 가리는 데서는 강한 자존심이, 등록금까지만 지원한 데서는 자립심을 중시하는 태도가 드러난다.', '김연수 「뉴욕제과점」 · 교과서 본문과 학습 노트', null, null, null, 28, null, null),
  ('korean-newyork-030', 'korean-newyork', 'choice', '어머니', '「뉴욕제과점」의 어머니', '어머니의 성격으로 나타나지 않은 것은?', null, '소극적이고 비관적임', array['억척스럽고 책임감 강함', '긍정적이고 낙천적임', '자존심이 강함'], '{}'::text[], '어머니는 과거엔 억척스럽고 책임감이 강했다. 수술 후 긍정적이고 낙천적인 성격으로 바뀌었고, 자존심이 강한 인물이다. 소극적이고 비관적인 인물이 아니다.', '김연수 「뉴욕제과점」 · 교과서 본문과 학습 노트', null, null, null, 29, null, null),
  ('korean-newyork-031', 'korean-newyork', 'choice', '어머니와 뉴욕제과점', '「뉴욕제과점」 · 뉴욕제과점의 전성기와 쇠퇴기', '이것과 겹쳐지는 것은?', null, '어머니 삶의 흐름', array['고향 마을의 역사', '''나''의 학창 시절', '아버지의 사업'], '{}'::text[], '뉴욕제과점의 전성기와 쇠퇴기는 어머니 삶의 흐름과 겹쳐진다.', '김연수 「뉴욕제과점」 · 교과서 본문과 학습 노트', null, null, null, 30, null, null),
  ('korean-newyork-032', 'korean-newyork', 'choice', '어머니와 뉴욕제과점', '「뉴욕제과점」 · ''나''에게 돈과 소중한 추억을 준 제과점', '뉴욕제과점이 형상화된 방식은?', null, '어머니의 분신처럼', array['''나''의 꿈처럼', '고향 사람들처럼', '도시 문명처럼'], '{}'::text[], '뉴욕제과점은 ''나''가 살아가는 데 필요한 돈과 소중한 추억까지 제공했다. 어머니의 분신처럼 형상화된다.', '김연수 「뉴욕제과점」 · 교과서 본문과 학습 노트', null, null, null, 31, null, null),
  ('korean-newyork-033', 'korean-newyork', 'choice', '어머니와 뉴욕제과점', '「뉴욕제과점」 · 뉴욕제과점이 ''나''에게 준 것', '이에 해당하지 않는 것은?', null, '고향을 떠날 이유', array['살아가는 데 필요한 돈', '소중한 추억', '정체성의 바탕'], '{}'::text[], '뉴욕제과점은 ''나''에게 살아가는 데 필요한 돈과 소중한 추억을 주었고, ''나''의 정체성을 기르는 데 큰 영향을 주었다.', '김연수 「뉴욕제과점」 · 교과서 본문과 학습 노트', null, null, null, 32, null, null),
  ('korean-newyork-034', 'korean-newyork', 'choice', '''나''와 고향 사람들', '「뉴욕제과점」 · 뉴욕제과점이 문을 닫았다', '''나'' A, 고향 사람들 B의 반응은? A–B는?', null, '놀람·큰일–무관심', array['무관심–놀람·큰일', '놀람·큰일–슬픔', '안도–무관심'], '{}'::text[], '''나''는 놀라며 큰일로 여기지만, 고향 사람들에게는 소중한 곳이 아니어서 관심이 없다.', '김연수 「뉴욕제과점」 · 교과서 본문과 학습 노트', null, null, null, 33, null, null),
  ('korean-newyork-035', 'korean-newyork', 'choice', '''나''와 고향 사람들', '「뉴욕제과점」 · 같은 일에 엇갈린 ''나''와 고향 사람들', '반응이 엇갈린 까닭은?', null, '소중한 추억이 있는지', array['고향에 사는지', '나이가 같은지', '빵을 좋아하는지'], '{}'::text[], '''나''에게 뉴욕제과점은 소중한 추억이 깃든 곳이지만, 고향 사람들에게는 그렇지 않기 때문이다.', '김연수 「뉴욕제과점」 · 교과서 본문과 학습 노트', null, null, null, 34, null, null),
  ('korean-newyork-036', 'korean-newyork', 'choice', '결말과 깨달음', '「뉴욕제과점」 결말 · ''나''가 생각하는 앞으로의 세상', '''나''의 생각으로 알맞은 것은?', null, '괴로운 일만 남은 건 아님', array['괴로운 일만 남아 있음', '즐거운 일만 남아 있음', '과거와 똑같이 흘러감'], '{}'::text[], '''나''는 앞으로 살 세상에 괴로운 일이 있겠지만, 괴로운 일만 남은 것은 아니라고 생각한다.', '김연수 「뉴욕제과점」 · 교과서 본문과 학습 노트', null, null, null, 35, null, null),
  ('korean-newyork-037', 'korean-newyork', 'choice', '결말과 깨달음', '「뉴욕제과점」 결말 · 추억으로 살아가는 자신을 본 ''나''', '''나''가 깨달은 것은?', null, '없는 것이 나를 살게 함', array['보이는 것이 전부임', '시간이 모든 걸 지움', '추억은 짐이 됨'], '{}'::text[], '뉴욕제과점이 만들어 준 추억으로 살아가는 자신을 보며, 존재하지 않는 무언가가 자신을 살아가게 한다는 것을 깨닫는다.', '김연수 「뉴욕제과점」 · 교과서 본문과 학습 노트', null, null, null, 36, null, null),
  ('korean-newyork-038', 'korean-newyork', 'choice', '결말과 깨달음', '「뉴욕제과점」 결말 · 사라진 제과점이 준 깨달음', '깨달음으로 옳지 않은 것은?', null, '보이는 것만이 전부임', array['사라진 것도 내 안에 있음', '삶에서 시간은 의미 없음', '없는 것이 나를 살게 함'], '{}'::text[], '삶에서 시간은 의미가 없고, 보이는 것만이 전부가 아니며, 사라졌다고 생각한 것이 내 안에 존재한다는 것이 ''나''의 깨달음이다.', '김연수 「뉴욕제과점」 · 교과서 본문과 학습 노트', null, null, null, 37, null, null),
  ('korean-newyork-039', 'korean-newyork', 'choice', '결말과 깨달음', '「뉴욕제과점」 결말 · 소중한 것들이 떠나 버릴 앞날', '이때 ''나''가 느낀 감정은?', null, '두려움', array['안도감', '희망', '통쾌함'], '{}'::text[], '앞으로 자신의 소중한 것들이 떠나 버릴 것이기에 ''나''는 두려움을 느낀다.', '김연수 「뉴욕제과점」 · 교과서 본문과 학습 노트', null, null, null, 38, null, null),
  ('korean-newyork-040', 'korean-newyork', 'choice', '결말과 깨달음', '「뉴욕제과점」 결말 · 어른이 되는 동안 제과점이 있었다는 것', '이것이 ''나''에게 준 마음은?', null, '안도감과 희망', array['두려움과 불안', '상실의 분노', '죄책감'], '{}'::text[], '''나''가 어른이 되는 동안 뉴욕제과점이 있었다는 것이 큰 도움이 되었다는 생각에서 안도감과 희망을 얻는다.', '김연수 「뉴욕제과점」 · 교과서 본문과 학습 노트', null, null, null, 39, null, null),
  ('korean-newyork-041', 'korean-newyork', 'choice', '결말과 깨달음', '「뉴욕제과점」 결말 · ''나''의 마음 변화', '변화의 순서로 알맞은 것은?', null, '두려움→안도·희망→깨달음', array['안도→두려움→깨달음', '깨달음→두려움→안도', '희망→체념→두려움'], '{}'::text[], '소중한 것들이 떠나리라는 두려움에서, 뉴욕제과점이 있었다는 데서 오는 안도감과 희망을 거쳐, 자신도 누군가에게 위안이 되리라는 깨달음에 이른다.', '김연수 「뉴욕제과점」 · 교과서 본문과 학습 노트', null, null, null, 40, null, null),
  ('korean-newyork-042', 'korean-newyork', 'choice', '결말과 깨달음', '「뉴욕제과점」 결말 · "내가 없어져도 누군가에게 오래 …"', '''나''가 바라는 자신의 모습은?', null, '오래 위안이 되는 사람', array['고향에 돌아가는 사람', '제과점을 잇는 사람', '모든 걸 잊는 사람'], '{}'::text[], '''나''는 자신도 없어진 뒤에 누군가에게 오래 위안이 되는 사람으로 남으리라고 생각한다.', '김연수 「뉴욕제과점」 · 교과서 본문과 학습 노트', null, null, null, 41, null, null),
  ('korean-newyork-043', 'korean-newyork', 'choice', '서술과 표현', '「뉴욕제과점」 · ''나''가 자신의 이야기를 고백하듯 들려준다', '이 시점의 효과로 알맞은 것은?', null, '''나''의 내면이 직접 드러남', array['여러 인물의 속마음을 고루 보임', '사건을 거리 두고 객관적으로 전함', '서술자가 모든 인물을 꿰뚫음'], '{}'::text[], '1인칭 주인공 시점이라 ''나''의 생각과 감정이 고백하듯 직접 드러나 독자가 ''나''의 심정에 쉽게 공감한다.', '김연수 「뉴욕제과점」 · 교과서 본문과 학습 노트', null, null, null, 42, null, null),
  ('korean-newyork-044', 'korean-newyork', 'choice', '서술과 표현', '「뉴욕제과점」 · 월남 파병, 한일 협정 같은 실제 시대 상황', '이를 언급한 효과로 알맞은 것은?', null, '제과점의 오랜 역사 강조', array['당시 정치를 비판함', '''나''의 출생 비밀을 밝힘', '어머니의 생각을 드러냄'], '{}'::text[], '그 모든 일이 ''나''가 태어나기도 전에 일어났다고 말해, 뉴욕제과점이 그만큼 오래전부터 거기 있었음을 실감 나게 보여 준다.', '김연수 「뉴욕제과점」 · 교과서 본문과 학습 노트', null, null, null, 43, null, null),
  ('korean-newyork-045', 'korean-newyork', 'choice', '서술과 표현', '「뉴욕제과점」의 서술상 특징', '서술상 특징으로 옳지 않은 것은?', null, '여러 서술자가 번갈아 서술함', array['1인칭 주인공 시점', '현재에서 과거를 회상함', '실제 연도로 사실감을 줌'], '{}'::text[], '''나'' 한 사람이 현재에서 과거를 회상하며 서술한다. 실제 연도와 시대 상황을 넣어 사실감을 준다. 서술자가 바뀌지 않는다.', '김연수 「뉴욕제과점」 · 교과서 본문과 학습 노트', null, null, null, 44, null, null),
  ('korean-newyork-046', 'korean-newyork', 'choice', '서술과 표현', '"하지만 과연 그런 것일까? 그저 사라져 버리면 그만일까?"', '이 물음이 하는 역할은?', null, '앞의 생각을 되짚으며 전환', array['앞 내용을 그대로 요약', '인물 간 갈등을 드러냄', '새 인물을 등장시킴'], '{}'::text[], '사라지는 것은 정상적인 일이라던 앞의 생각에 스스로 의문을 던져, 사라진 것이 내 안에 남는다는 뒤의 깨달음으로 넘어가게 한다.', '김연수 「뉴욕제과점」 · 교과서 본문과 학습 노트', null, null, null, 45, null, null),
  ('korean-newyork-047', 'korean-newyork', 'choice', '서술과 표현', '"어차피 인생이란 그런 게 아니겠는가."', '이 문장에 쓰인 표현법은?', null, '설의법', array['반어법', '직유법', '도치법'], '{}'::text[], '답이 분명한 내용을 물음의 형식으로 표현해 뜻을 강조하는 설의법이다. 인생이란 원래 그런 것이라는 뜻이다.', '김연수 「뉴욕제과점」 · 교과서 본문과 학습 노트', null, null, null, 46, null, null),
  ('korean-newyork-048', 'korean-newyork', 'choice', '서술과 표현', '"사탕을 넣어 둔 유리 항아리 뚜껑을 자꾸만 열어 대는 아이처럼"', '이 표현의 방식과 뜻은?', null, '직유: 추억을 자꾸 꺼내 봄', array['은유: 사탕이 먹고 싶음', '의인: 항아리가 말을 함', '반어: 추억을 버리고 싶음'], '{}'::text[], '''~처럼''을 쓴 직유다. 마음속에 간직한 불빛(추억)들을 아이가 사탕 항아리를 열어 보듯 자꾸 꺼내 보는 모습을 나타낸다.', '김연수 「뉴욕제과점」 · 교과서 본문과 학습 노트', null, null, null, 47, null, null),
  ('korean-newyork-049', 'korean-newyork', 'choice', '서술과 표현', '"그곳에서 나는 어린아이였다가 초등학생이었다가 … 대학생이기도 했다."', '이 문장이 드러내는 것은?', null, '모든 시절의 ''나''가 그곳에 있음', array['''나''가 나이를 잊어버렸음', '가게에 늘 손님이 많았음', '''나''가 빨리 어른이 되었음'], '{}'::text[], '어린 시절부터 대학생 때까지 ''나''의 모든 시절이 뉴욕제과점에 담겨 있다. 뉴욕제과점과 함께 ''나''가 자랐음을 보여 준다.', '김연수 「뉴욕제과점」 · 교과서 본문과 학습 노트', null, null, null, 48, null, null),
  ('korean-newyork-050', 'korean-newyork', 'choice', '서술과 표현', '「뉴욕제과점」 · 진열대, 테이블, 텔레비전 자리까지 옛 가게를 자세히 그림', '이렇게 묘사한 효과는?', null, '마음속 가게를 생생히 되살림', array['가게의 구조를 비판함', '국밥집을 홍보함', '시간의 흐름을 빠르게 함'], '{}'::text[], '''나''의 마음속에 영원히 남은 뉴욕제과점의 모습을 하나하나 떠올려, 그곳이 얼마나 생생하고 소중한 기억인지 보여 준다.', '김연수 「뉴욕제과점」 · 교과서 본문과 학습 노트', null, null, null, 49, null, null),
  ('korean-newyork-051', 'korean-newyork', 'choice', '소재와 상징', '"내 안에 간직한 불빛들을 하나둘 꺼내 보는 일이 잦다"', '여기서 불빛이 뜻하는 것은?', null, '마음속에 간직한 추억', array['역전 거리의 가로등', '앞날에 대한 두려움', '가게의 전기 요금'], '{}'::text[], '불빛은 ''나''가 마음속에 간직한 소중한 추억이다. 그 불빛들의 중심에는 늘 뉴욕제과점이 있다.', '김연수 「뉴욕제과점」 · 교과서 본문과 학습 노트', null, null, null, 50, null, null),
  ('korean-newyork-052', 'korean-newyork', 'choice', '소재와 상징', '"추억 속에서 조금씩 밝혀지는 그 불빛들의 중심에는 뉴욕제과점이 …"', '뉴욕제과점의 의미로 알맞은 것은?', null, '''나''의 추억의 중심', array['잊고 싶은 과거의 장소', '고향 사람들의 만남 장소', '어머니가 떠나고 싶던 곳'], '{}'::text[], '''나''의 추억은 불빛처럼 밝혀지는데, 그 중심에 늘 뉴욕제과점이 있다. 뉴욕제과점은 ''나''의 추억의 중심이다.', '김연수 「뉴욕제과점」 · 교과서 본문과 학습 노트', null, null, null, 51, null, null),
  ('korean-newyork-053', 'korean-newyork', 'choice', '소재와 상징', '"나는 뉴욕제과점에서 태어나지도 않았는데 … 막내아들이라고 불렀다."', '이 구절이 드러내는 것은?', null, '제과점이 ''나''의 일부임', array['''나''가 제과점을 싫어함', '사람들이 ''나''를 놀림', '''나''가 가게를 물려받음'], '{}'::text[], '사람들이 ''나''를 뉴욕제과점 막내아들이라 부를 만큼 뉴욕제과점은 ''나''를 이루는 일부였다.', '김연수 「뉴욕제과점」 · 교과서 본문과 학습 노트', null, null, null, 52, null, null),
  ('korean-newyork-054', 'korean-newyork', 'choice', '소재와 상징', '국밥집에서 "내 눈길이 닿는 모든 곳에서 나는 우리 가족의 모습을 볼 수 있었다."', '이 장면이 보여 주는 것은?', null, '현재 위에 과거가 겹쳐 보임', array['가족이 실제로 와 있음', '가족을 잊고 싶어 함', '국밥집이 마음에 듦'], '{}'::text[], '국밥집으로 바뀐 현재의 공간 위에 옛 뉴욕제과점과 가족의 모습이 겹쳐 떠오른다. 사라진 것이 ''나''의 기억 속에 살아 있다.', '김연수 「뉴욕제과점」 · 교과서 본문과 학습 노트', null, null, null, 53, null, null),
  ('korean-newyork-055', 'korean-newyork', 'choice', '소재와 상징', '「뉴욕제과점」 · 국밥집에서 옛 2번 테이블쯤 되는 자리에 앉은 ''나''', '이 행동의 의미로 알맞은 것은?', null, '옛 가게의 기억을 더듬음', array['가장 싼 자리를 고름', '사람을 피해 숨음', '새 가게를 평가함'], '{}'::text[], '''나''는 옛 뉴욕제과점의 자리를 떠올리며 2번 테이블이 있던 곳에 앉는다. 사라진 가게의 기억을 더듬는 행동이다.', '김연수 「뉴욕제과점」 · 교과서 본문과 학습 노트', null, null, null, 54, null, null),
  ('korean-newyork-056', 'korean-newyork', 'choice', '사라져 가는 제과점', '「뉴욕제과점」 · 새로운 빵집들 사이에서 점점 기울어 간 가게', '뉴욕제과점이 쇠퇴한 까닭이 아닌 것은?', null, '손님들이 빵을 싫어하게 됨', array['대기업 빵집들이 생김', '새로 바뀔 능력이 없었음', '어머니의 건강이 나빠짐'], '{}'::text[], '세련된 제과점과 대기업 빵집이 들어서고, 새롭게 바뀔 능력이 없었으며, 가게를 이끌던 어머니의 건강마저 나빠져 뉴욕제과점은 쇠락했다.', '김연수 「뉴욕제과점」 · 교과서 본문과 학습 노트', null, null, null, 55, null, null),
  ('korean-newyork-057', 'korean-newyork', 'choice', '사라져 가는 제과점', '「뉴욕제과점」 · 1980년대풍으로 끝까지 자리를 지킨 가게', '이 모습에서 짐작되는 것은?', null, '변화에 적응하지 못함', array['유행을 앞서 이끎', '장사가 아주 잘됨', '대기업과 손잡음'], '{}'::text[], '다른 가게들이 업종을 바꿀 때 뉴욕제과점은 1980년대풍 그대로 자리를 지켰다. 새롭게 바뀐 환경에 적응하지 못한 것이다.', '김연수 「뉴욕제과점」 · 교과서 본문과 학습 노트', null, null, null, 56, null, null),
  ('korean-newyork-058', 'korean-newyork', 'choice', '사라져 가는 제과점', '"기레빠시도 버리지 않고 다 먹었던 분이었는데, 그 모습을 바라보는 심정은"', '''나''의 심정은?', null, '처참함', array['통쾌함', '홀가분함', '무덤덤함'], '{}'::text[], '자투리 빵도 버리지 않던 어머니가 팔지 못한 빵을 내다 버리는 모습을 보며 ''나''는 매우 처참한 심정이 된다.', '김연수 「뉴욕제과점」 · 교과서 본문과 학습 노트', null, null, null, 57, null, null),
  ('korean-newyork-059', 'korean-newyork', 'choice', '사라져 가는 제과점', '"니가 아직 대학교도 졸업하지 못했는데, 가게 그만두면 네 등록금은 …"', '어머니가 가게를 놓지 못한 마음은?', null, '자식에 대한 책임감', array['가게에 대한 싫증', '돈에 대한 욕심', '남의 시선에 대한 걱정'], '{}'::text[], '어머니는 막내의 등록금을 걱정하며 가게를 그만두지 못한다. 자식을 끝까지 책임지려는 마음이다.', '김연수 「뉴욕제과점」 · 교과서 본문과 학습 노트', null, null, null, 58, null, null),
  ('korean-newyork-060', 'korean-newyork', 'choice', '사라져 가는 제과점', '「뉴욕제과점」 · 빙수를 가장 많이 판 날, 그 숫자를 외워 둔 ''나''', '''나''가 숫자를 외운 마음은?', null, '어머니에게 자랑하고 싶음', array['장사를 그만두고 싶음', '용돈을 받고 싶음', '어머니를 걱정시키려 함'], '{}'::text[], '입원한 어머니에게 자랑하려고 숫자를 외웠다. 가게를 잘 지켜 어머니에게 기쁨을 드리고 싶은 마음이다.', '김연수 「뉴욕제과점」 · 교과서 본문과 학습 노트', null, null, null, 59, null, null),
  ('korean-newyork-061', 'korean-newyork', 'choice', '사라져 가는 제과점', '"그래, 많이 팔았네." / "그거보다는 내가 더 많이 팔았지."', '두 말에 드러난 어머니의 마음은?', null, '기특함과 자부심', array['서운함과 원망', '걱정과 불안', '무관심과 귀찮음'], '{}'::text[], '어머니는 아들을 기특하게 여기면서도, 예전에는 자신이 더 많이 팔았다며 뉴욕제과점을 꾸려 온 일에 자부심을 드러낸다.', '김연수 「뉴욕제과점」 · 교과서 본문과 학습 노트', null, null, null, 60, null, null),
  ('korean-newyork-062', 'korean-newyork', 'choice', '사라져 가는 제과점', '"번 돈이 전성기 때 … 며칠 번 돈만큼도 되지 않았다. 갑자기 겁이 덜컥 났다."', '''나''가 겁이 난 까닭은?', null, '홀로 서는 일의 막막함', array['어머니의 병이 깊어짐', '제과점이 팔림', '글을 못 쓰게 됨'], '{}'::text[], '스스로 벌어 살아야 하는데 열심히 번 돈이 제과점 며칠 매상만도 못하자, 홀로 살아갈 일이 막막하게 느껴진 것이다.', '김연수 「뉴욕제과점」 · 교과서 본문과 학습 노트', null, null, null, 61, null, null),
  ('korean-newyork-063', 'korean-newyork', 'choice', '사라져 가는 제과점', '"어머니도 당신이 문을 연 뉴욕제과점이 이제 그 생명을 다했다는 사실을 납득하는 것 같았다."', '어머니의 변화로 알맞은 것은?', null, '제과점의 끝을 받아들임', array['다시 일어서려 함', '가게를 팔고 기뻐함', '''나''를 원망함'], '{}'::text[], '시간이 흐를수록 어머니도 뉴욕제과점이 끝나 간다는 사실을 받아들이게 된다. ''나''는 그 기분을 상상조차 하기 어렵다.', '김연수 「뉴욕제과점」 · 교과서 본문과 학습 노트', null, null, null, 62, null, null),
  ('korean-newyork-064', 'korean-newyork', 'choice', '사라져 가는 제과점', '「뉴욕제과점」 · 국밥집이 된다는 소식에 "나는 잘됐다고 말했다."', '그때 ''나''가 크게 슬퍼하지 않은 까닭은?', null, '내 문제로도 걱정이 많아서', array['제과점을 싫어해서', '국밥집을 좋아해서', '이미 다시 열 계획이어서'], '{}'::text[], '조금 쓸쓸했지만, 그 당시 ''나''는 제 문제만으로도 걱정할 일이 많아 심각하게 생각하지 않았다.', '김연수 「뉴욕제과점」 · 교과서 본문과 학습 노트', null, null, null, 63, null, null),
  ('korean-newyork-065', 'korean-newyork', 'choice', '사라져 가는 제과점', '"국밥집으로 바뀐 뒤로 뉴욕제과점이 있던 곳으로는 한 번도 가지 않았다."', '이 행동에 담긴 마음은?', null, '변한 모습을 보기 싫음', array['길을 잊어버림', '국밥을 싫어함', '고향 사람이 싫음'], '{}'::text[], '추억의 장소가 다른 가게로 바뀐 모습을 마주하기가 싫었던 것이다. 그만큼 그곳은 ''나''에게 소중했다.', '김연수 「뉴욕제과점」 · 교과서 본문과 학습 노트', null, null, null, 64, null, null),
  ('korean-newyork-066', 'korean-newyork', 'choice', '''나''와 고향 사람들', '"어떤 의미에서 나는 실향민이나 마찬가지다."', '''나''가 이렇게 말한 까닭은?', null, '살던 거리가 모두 사라져서', array['북에서 내려온 피란민이라서', '고향에 갈 수 없어서', '이사를 자주 다녀서'], '{}'::text[], '고향은 그대로 있지만 ''나''가 살던 거리의 작은 상점들은 개발로 모두 사라졌다. 그래서 고향을 잃은 사람과 같다고 느낀다.', '김연수 「뉴욕제과점」 · 교과서 본문과 학습 노트', null, null, null, 65, null, null),
  ('korean-newyork-067', 'korean-newyork', 'choice', '''나''와 고향 사람들', '"개발은 그 모든 작은 상점들을 없애 버렸다. 대단히 쓸쓸한 일이다."', '개발에 대한 ''나''의 태도는?', null, '작은 것들의 소멸을 쓸쓸해함', array['개발을 적극적으로 반김', '상점 주인들을 탓함', '개발은 나와 상관없다고 봄'], '{}'::text[], '''나''는 개발로 어린 시절의 작은 상점들이 사라진 것을 쓸쓸하게 여긴다.', '김연수 「뉴욕제과점」 · 교과서 본문과 학습 노트', null, null, null, 66, null, null),
  ('korean-newyork-068', 'korean-newyork', 'choice', '''나''와 고향 사람들', '「뉴욕제과점」 · 미팅까지 했던 곳이 사라졌다는데 놀라지 않는 고향 사람들', '''나''가 의아하게 여긴 것은?', null, '추억의 장소가 사라져도 담담함', array['미팅 장소가 많았던 것', '고향이 하나도 변하지 않음', '제과점 빵값이 비쌌던 것'], '{}'::text[], '''나''는 추억이 깃든 곳이 사라졌다면 놀랄 만한 일인데도 고향 사람들이 놀라거나 충격받지 않는 것을 의아하게 여긴다.', '김연수 「뉴욕제과점」 · 교과서 본문과 학습 노트', null, null, null, 67, null, null),
  ('korean-newyork-069', 'korean-newyork', 'choice', '결말과 깨달음', '「뉴욕제과점」 결말 · "그즈음 내게는 아이가 생겼다."', '이 일이 ''나''의 깨달음에 준 계기는?', null, '나 없이도 누군가 살아감', array['돈을 더 벌어야 함', '고향에 돌아가야 함', '제과점을 다시 열어야 함'], '{}'::text[], '아이가 생기면서 ''나''는 자신이 사라진 뒤에도 누군가 세상을 살아가며, 자신도 그에게 위안으로 남을 수 있음을 깨닫는다.', '김연수 「뉴욕제과점」 · 교과서 본문과 학습 노트', null, null, null, 68, null, null),
  ('korean-newyork-070', 'korean-newyork', 'choice', '결말과 깨달음', '"어차피 인생은 그런 것이니까 이걸 비관적으로 생각해서는 안 된다, 하고 …"', '이 다짐에 담긴 ''나''의 마음은?', null, '상실을 애써 받아들이려 함', array['제과점 폐업을 반기려 함', '어머니를 탓하려 함', '고향을 아예 잊으려 함'], '{}'::text[], '''나''는 뉴욕제과점이 사라진 일을 비관하지 않으려고 몇 번이나 다짐한다. 상실의 아픔을 애써 받아들이려는 마음이다.', '김연수 「뉴욕제과점」 · 교과서 본문과 학습 노트', null, null, null, 69, null, null),
  ('korean-newyork-written-001', 'korean-newyork', 'written', '어머니와 뉴욕제과점', null, '「뉴욕제과점」에서 뉴욕제과점이 어머니의 분신처럼 형상화되었다고 볼 수 있는 까닭을 두 가지 쓰시오.', null, '뉴욕제과점의 전성기와 쇠퇴기가 어머니 삶의 흐름과 겹쳐진다. 또 뉴욕제과점은 어머니처럼 ''나''가 살아가는 데 필요한 돈과 소중한 추억까지 ''나''에게 주었다. 그래서 뉴욕제과점은 어머니의 분신처럼 형상화된다.', '{}'::text[], array['제과점의 전성기·쇠퇴기 = 어머니 삶의 흐름', '''나''에게 돈과 소중한 추억을 줌', '어머니의 분신으로 형상화됨을 밝힘'], '', '김연수 「뉴욕제과점」 · 교과서 본문과 학습 노트', null, null, null, 1000, null, null),
  ('korean-newyork-written-002', 'korean-newyork', 'written', '구절의 의미', null, '「뉴욕제과점」에서 ''나''가 "정상적인 세상에서 … 정상적인 일이다"처럼 ''정상적''을 되풀이한 표현의 효과를 쓰시오.', null, '''정상적''을 네 번 되풀이하며 먼저 생긴 것이 먼저 없어지는 것은 당연한 일이라고 말한다. 그러나 이는 겉말과 속뜻이 다른 반어적 표현으로, 뉴욕제과점이 사라진 데서 오는 상실감을 오히려 강조한다.', '{}'::text[], array['''정상적''의 반복 · 먼저 생긴 것이 먼저 없어짐', '반어적 표현임', '뉴욕제과점이 사라진 상실감 강조'], '', '김연수 「뉴욕제과점」 · 교과서 본문과 학습 노트', null, null, null, 1001, null, null),
  ('korean-newyork-written-003', 'korean-newyork', 'written', '''나''와 고향 사람들', null, '「뉴욕제과점」에서 뉴욕제과점이 문을 닫은 일에 대한 ''나''와 고향 사람들의 반응을 비교하고, 반응이 다른 까닭을 쓰시오.', null, '''나''는 뉴욕제과점이 문을 닫은 일에 놀라며 큰일로 여기지만, 고향 사람들은 관심이 없다. ''나''에게 뉴욕제과점은 유년의 소중한 추억이 깃들고 정체성을 기른 곳이지만, 고향 사람들에게는 소중한 곳이 아니기 때문이다.', '{}'::text[], array['''나'': 놀람, 큰일로 여김', '고향 사람들: 관심 없음', '''나''에게만 소중한 추억·정체성의 장소'], '', '김연수 「뉴욕제과점」 · 교과서 본문과 학습 노트', null, null, null, 1002, null, null),
  ('korean-newyork-written-004', 'korean-newyork', 'written', '결말과 깨달음', null, '「뉴욕제과점」 결말에서 ''나''의 마음이 어떻게 바뀌는지 순서대로 쓰고, ''나''가 마지막에 깨달은 것을 쓰시오.', null, '''나''는 앞으로 소중한 것들이 떠나 버릴 것이기에 두려움을 느낀다. 그러나 어른이 되는 동안 뉴욕제과점이 있었다는 것이 큰 도움이 되었음을 떠올리며 안도감과 희망을 얻는다. 마침내 자신도 없어진 뒤에 누군가에게 오래 위안이 되는 사람으로 남으리라는 것을 깨닫는다.', '{}'::text[], array['두려움: 소중한 것들이 떠나 버릴 것', '안도감·희망: 뉴욕제과점이 있었다는 것이 도움이 됨', '깨달음: 나도 누군가에게 오래 위안이 되는 사람으로 남음'], '', '김연수 「뉴욕제과점」 · 교과서 본문과 학습 노트', null, null, null, 1003, null, null),
  ('practice-short-korean-newyork-001', 'korean-newyork', 'written', '갈래와 구성', null, '「뉴욕제과점」

이 작품의 갈래는? (답을 하나만 쓰세요.)', null, '자전적 소설', '{}'::text[], array['정답: 자전적 소설'], '', '김연수 「뉴욕제과점」 · 교과서 본문과 학습 노트', null, null, null, 1004, null, null),
